/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { PolyRing, PuiseuxPoly, PuiseuxRing, PythonMPQ, QQ, Sym, ZZ, pow, pprintUseUnicode, puiseuxRing, rational, ring, symbols, sympify, xreplace } from '../../src';
import { at, pyRepr, pyStr, sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.polys.puiseux", () => {
  // a primitive result that no library call returned
  //   p2.monom # x*y**2
  //   => (1, 2)
  it.todo("p2.monom # x*y**2");
  it("p2.poly", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PuiseuxRing([x, y], QQ).fromDict([[[rational(-1), rational(0)], rational(1)], [[rational(0), rational(-2)], rational(1)]]).poly)).toBe('x + y**2');
  });
  it("(y**2 + x) / (x*y**2) == p2", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PuiseuxRing([x, y], QQ).fromDict([[[rational(0), rational(-2)], rational(1)], [[rational(-1), rational(0)], rational(1)]]).equals(new PuiseuxRing([x, y], QQ).fromDict([[[rational(-1), rational(0)], rational(1)], [[rational(0), rational(-2)], rational(1)]])))).toBe('True');
  });
  // a primitive result that no library call returned
  //   p3.ns
  //   => (2, 3)
  it.todo("p3.ns");
  it("p3.poly", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PuiseuxRing([x, y], QQ).fromDict([[[rational(1, 2), rational(0)], rational(1)], [[rational(0), rational(2, 3)], rational(1)]]).poly)).toBe('x + y**2');
  });
  it("p.as_expr()", () => {
    const x = new Sym('x');
    expect(sympyStr(new PuiseuxRing([x], QQ).fromDict([[[rational(2)], rational(5)], [[rational(3)], rational(7)]]).asExpr())).toBe('7*x**3 + 5*x**2');
  });
  it("p.diff(x)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PuiseuxRing([x, y], QQ).fromDict([[[rational(2), rational(0)], rational(5)], [[rational(0), rational(3)], rational(7)]]).diff(new PuiseuxRing([x, y], QQ).fromDict([[[rational(1), rational(0)], rational(1)]])))).toBe('10*x');
  });
  it("p.diff(y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PuiseuxRing([x, y], QQ).fromDict([[[rational(2), rational(0)], rational(5)], [[rational(0), rational(3)], rational(7)]]).diff(new PuiseuxRing([x, y], QQ).fromDict([[[rational(0), rational(1)], rational(1)]])))).toBe('21*y**2');
  });
  it("PuiseuxPoly.from_dict({(QQ(1,2),): QQ(3)}, R)", () => {
    const x = new Sym('x');
    expect(sympyStr(PuiseuxPoly.fromDict(new Map([[[rational(1, 2)], rational(3)]]), new PuiseuxRing([x], QQ)))).toBe('3*x**(1/2)');
  });
  it("R.from_dict({(QQ(1,2),): QQ(3)})", () => {
    const x = new Sym('x');
    expect(sympyStr(new PuiseuxRing([x], QQ).fromDict(new Map([[[rational(1, 2)], rational(3)]])))).toBe('3*x**(1/2)');
  });
  it("p[(2, 0)]", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PuiseuxRing([x, y], QQ).fromDict([[[rational(2), rational(0)], rational(5)], [[rational(0), rational(3)], rational(7)]]).getitem([sympify(2), sympify(0)]))).toBe('5');
  });
  it("f.diff(x)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PuiseuxRing([x, y], QQ).fromDict([[[rational(2), rational(0)], rational(1)], [[rational(0), rational(3)], rational(1)]]).diff(new PuiseuxRing([x, y], QQ).fromDict([[[rational(1), rational(0)], rational(1)]])))).toBe('2*x');
  });
  it("f.diff(x) (2)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PuiseuxRing([x, y], QQ).fromDict([[[rational(-1), rational(0)], rational(1)], [[rational(0), rational(-2)], rational(1)]]).diff(new PuiseuxRing([x, y], QQ).fromDict([[[rational(1), rational(0)], rational(1)]])))).toBe('-1*x**(-2)');
  });
  it("R.domain_new(3)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PuiseuxRing([x], QQ).domainNew(rational(3)))).toBe('3');
  });
  it("R.from_dict({(QQ(1,2),): QQ(3)}) (2)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PuiseuxRing([x], QQ).fromDict(new Map([[[rational(1, 2)], rational(3)]])))).toBe('3*x**(1/2)');
  });
  // the arguments do not type-check against the public API
  //   R.from_int(3)
  //   => 3
  it.todo("R.from_int(3)");
  it("R2.from_poly(x1**2)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PuiseuxRing([x], QQ).fromPoly(new PolyRing([x], QQ, 'lex').fromExpr(xreplace(pow(x, 2), []))))).toBe('x**2');
  });
  it("R.ground_new(3)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PuiseuxRing([x], QQ).groundNew(rational(3)))).toBe('3');
  });
  it("R.index(x)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PuiseuxRing([x, y], QQ).index(new PuiseuxRing([x, y], QQ).fromDict([[[rational(1), rational(0)], rational(1)]])))).toBe('0');
  });
  it("R.index(y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PuiseuxRing([x, y], QQ).index(new PuiseuxRing([x, y], QQ).fromDict([[[rational(0), rational(1)], rational(1)]])))).toBe('1');
  });
  it("R", () => {
    expect(sympyStr(at(puiseuxRing('x y', QQ), 0))).toBe('PuiseuxRing((x, y), QQ)');
  });
});

